UPDATE pw_platform_ai_connection
SET config = CASE WHEN #{baseUrl} IS NULL THEN json_build_object()
                  ELSE jsonb_set(config::jsonb, '{baseUrl}', to_jsonb(#{baseUrl}::text), true)::json END,
    enabled = CASE WHEN #{enabled} THEN 1 ELSE 0 END,
    sort_order = #{sortOrder}
WHERE connection_key = #{connectionKey}

UPDATE pw_platform_ai_connection
SET credentials_configured = CASE WHEN #{configured} THEN 1 ELSE 0 END
WHERE connection_key = #{connectionKey}
